      g.addColorStop(0, "rgba(255,255,255,1)"); g.addColorStop(.16, "rgba(255,255,255,.6)");
      g.addColorStop(.42, "rgba(255,255,255,.16)"); g.addColorStop(1, "rgba(255,255,255,0)");
      x.fillStyle = g; x.fillRect(0, 0, n, n);
