      bg.setAttribute("aPh", new T.Float32BufferAttribute(ph, 1));
      bg.setAttribute("aCol", new T.Float32BufferAttribute(col, 3));
      var u = { uTime: { value: 0 }, uSize: { value: 10 } };
      var pts = new T.Points(bg, additive(new T.ShaderMaterial({
        uniforms: u,
        vertexShader: "uniform float uTime;uniform float uSize;attribute float aPh;attribute vec3 aCol;varying vec3 vC;varying float vA;void main(){vec4 mv=modelViewMatrix*vec4(position,1.);vA=.62+.3*sin(uTime*1.1+aPh);vC=aCol;gl_PointSize=uSize;gl_Position=projectionMatrix*mv;}",
        fragmentShader: "varying vec3 vC;varying float vA;void main(){float d=length(gl_PointCoord-.5);float a=(smoothstep(.2,.06,d)+smoothstep(.5,.1,d)*.16)*vA;gl_FragColor=linearToOutputTexel(vec4(vC*a,a));}"
      }), true));
